import type { NextConfig } from "next";
import createNextIntlPlugin from "next-intl/plugin";

// All /api traffic proxies to the standalone API app (apps/api), so browser
// calls stay same-origin — cookies and SSE flow through without CORS setup.
// stellar.toml (SEP-1) is generated by the API too and served from this
// domain, which wallets and explorers look up.
const API_URL = process.env.API_URL ?? "http://localhost:4000";

const nextConfig: NextConfig = {
  async rewrites() {
    return [
      { source: "/api/:path*", destination: `${API_URL}/api/:path*` },
      { source: "/.well-known/stellar.toml", destination: `${API_URL}/.well-known/stellar.toml` },
    ];
  },
};

export default createNextIntlPlugin()(nextConfig);
